# Sestaví pruvodce/index.html z navrh/pruvodce.html (obalí hlavičkou s ikonami). Spouštět z kořene repozitáře.
{ printf '<!DOCTYPE html>\n<html lang="cs">\n<head>\n<meta charset="UTF-8" />\n<meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover" />\n<meta name="theme-color" content="#f6f4ef" />\n<link rel="icon" href="../ikony/favicon-32.png" sizes="32x32" type="image/png" />\n<link rel="icon" href="../ikony/favicon-64.png" sizes="64x64" type="image/png" />\n<link rel="apple-touch-icon" href="../ikony/apple-touch-icon.png" />\n<style>body{margin:0}[hidden]{display:none!important}img{max-width:100%%}</style>\n<script>window.IMGBASE="../obrazky/";</script>\n</head>\n<body>\n'; cat navrh/pruvodce.html; printf '\n</body>\n</html>\n'; } > pruvodce/index.html
